// ROVER discovery: self-prime secureConfig, run the session, page the grid
// (DESC by last-updated) until we reach the high-water mark or the per-run cap.
// Pure HTTP (no browser). Emits one item per NEW towing-relevant approval, plus a
// trailing __control row (so crawl-health always runs, even on a 0-result week).
const HOST = 'https://www.rover.infrastructure.gov.au';
const GRID = 'c8825c88-ebd8-ee11-904d-000d3a7a0265';
const UA = 'Mozilla/5.0 (X11; Linux x86_64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/124.0 Safari/537.36';
const MAX_NEW = 25;   // per-run cap on approvals (politeness / backfill throttle)
const MAX_PAGES = 10; // safety cap
const PAGE_SIZE = 50;
const KEEP = /^(M[A-E]?|N[ABC]\d?)$/i; // towing-relevant: passenger M*, goods N*; excludes T* trailers, L*, O*
const helpers = this.helpers;
const sd = $getWorkflowStaticData('global');
const highWater = sd.roverHighWaterMs || 0;
const jar = {};
const cookieHeader = () => Object.entries(jar).map(([k, v]) => k + '=' + v).join('; ');
const absorb = (sc) => (sc || []).forEach((c) => { const p = String(c).split(';')[0]; const i = p.indexOf('='); if (i > 0) jar[p.slice(0, i).trim()] = p.slice(i + 1).trim(); });
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
const jitter = () => 2500 + Math.floor(Math.random() * 4500);
async function http(method, url, body, extra) {
  const headers = { 'User-Agent': UA, Accept: '*/*', 'Accept-Language': 'en-AU,en;q=0.9', ...(extra || {}) };
  if (Object.keys(jar).length) headers.Cookie = cookieHeader();
  const opts = { method, url, headers, returnFullResponse: true, ignoreHttpStatusErrors: true };
  if (body != null) { headers['Content-Type'] = 'application/json'; opts.body = body; }
  const res = await helpers.httpRequest(opts);
  absorb(res.headers && (res.headers['set-cookie'] || res.headers['Set-Cookie']));
  if ([403, 429, 503].includes(res.statusCode)) throw new Error('ROVER ' + res.statusCode + ' (' + url + ') — possible rate-limit/block; aborting run');
  if (res.statusCode >= 400) throw new Error('ROVER ' + method + ' ' + url + ' -> ' + res.statusCode);
  return res;
}
const attr = (r, n) => { const a = (r.Attributes || []).find((x) => x.Name === n); return a ? (a.Value && a.Value.Value !== undefined ? a.Value.Value : a.Value) : null; };
const dotnet = (s) => { const m = String(s).match(/\/Date\((\d+)\)\//); return m ? parseInt(m[1], 10) : null; };
// 1. directory -> secureConfig (+ session cookies)
const dir = await http('GET', HOST + '/PublishedApprovals/VTAApprovals/');
const vlm = String(dir.body).match(/data-view-layouts=(["'])([\s\S]*?)\1/);
if (!vlm) throw new Error('data-view-layouts not found — ROVER page layout changed');
const layouts = JSON.parse(Buffer.from(vlm[2].replace(/&quot;/g, '"').replace(/&amp;/g, '&'), 'base64').toString('utf8'));
const secureConfig = (layouts[0] || {}).Base64SecureConfiguration;
if (!secureConfig) throw new Error('Base64SecureConfiguration missing from view-layouts');
// 2. CSRF token
const tok = await http('GET', HOST + '/_layout/tokenhtml');
const token = (String(tok.body).match(/value="([^"]+)"/) || [])[1];
if (!token) throw new Error('CSRF token not found');
// 3. page the grid (newest-updated first) until older than high-water or caps hit
const found = [];
let stop = false;
for (let page = 1; page <= MAX_PAGES && !stop && found.length < MAX_NEW; page++) {
  if (page > 1) await sleep(jitter());
  const grid = await http('POST', HOST + '/_services/entity-grid-data.json/' + GRID,
    JSON.stringify({ base64SecureConfiguration: secureConfig, sortExpression: 'rvr_publishedlastupdatedate DESC', search: null, page, pageSize: PAGE_SIZE, filter: null, metaFilter: null }),
    { __RequestVerificationToken: token, 'X-Requested-With': 'XMLHttpRequest' });
  const data = typeof grid.body === 'string' ? JSON.parse(grid.body) : grid.body;
  const recs = data.Records || [];
  if (!recs.length) break;
  for (const r of recs) {
    const ms = dotnet(attr(r, 'rvr_publishedlastupdatedate'));
    if (ms != null && ms <= highWater) { stop = true; break; } // reached already-imported
    const cat = String(attr(r, 'cv.rvr_categorytype') || '');
    if (!KEEP.test(cat)) continue;
    const id = attr(r, 'rvr_approvalid') || r.Id;
    if (!id) continue;
    found.push({ approvalId: id, vta: attr(r, 'rvr_approvalnumber'), make: attr(r, 'cv.rvr_manufacturer'), model: attr(r, 'cv.rvr_model'), category: cat, updatedMs: ms });
    if (found.length >= MAX_NEW) { stop = true; break; }
  }
  if (!data.MoreRecords) break;
}
const out = found.map((f) => ({ json: f }));
out.push({ json: { __control: true, found: found.length, firstRun: highWater === 0 } });
return out;

// Crawl-health: always runs (off the __control row). Tracks the per-run found-count
// history and raises crawlHealthAlert when a run finds 0 new while it normally finds
// some — i.e. the scraper is probably broken, not the world (a 0-new run looks
// identical to "no new approvals"). Structural breakage already throws upstream.
const sd = $getWorkflowStaticData('global');
const ctrl = $input.all().map((i) => i.json).find((j) => j && j.__control) || { found: 0 };
const hist = Array.isArray(sd.roverRecentCounts) ? sd.roverRecentCounts : [];
hist.push(ctrl.found || 0);
while (hist.length > 8) hist.shift();
sd.roverRecentCounts = hist;
const usuallyFinds = hist.length >= 4 && hist.slice(0, -1).some((n) => n > 0);
const crawlHealthAlert = (ctrl.found || 0) === 0 && usuallyFinds;
return [{ json: { found: ctrl.found || 0, recentCounts: hist, crawlHealthAlert, highWaterMs: sd.roverHighWaterMs || 0 } }];

// Process new approvals (throttled, sequential, oldest-first). For each: fetch the
// public VTADetails page, POST its HTML to the app's /api/rover/ingest (the app
// extracts + gates), then advance the high-water mark — but only AFTER a successful
// ingest, processed oldest-first, so a mid-run block leaves a clean, contiguous
// watermark (next run resumes exactly where this stopped; ingest is idempotent).
const HOST = 'https://www.rover.infrastructure.gov.au';
const UA = 'Mozilla/5.0 (X11; Linux x86_64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/124.0 Safari/537.36';
const APP = ('https://tbr.dev.ragebots.me').replace(/\/$/, '');
const TOKEN = '__ROVER_INGEST_TOKEN__'; // injected on import — this n8n blocks $env in Code nodes
if (!TOKEN || TOKEN === '__ROVER_INGEST_TOKEN__') throw new Error('ROVER_INGEST_TOKEN sentinel not replaced — inject the token on import');
const helpers = this.helpers;
const sd = $getWorkflowStaticData('global');
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
const jitter = () => 4000 + Math.floor(Math.random() * 6000); // 4–10s between ROVER hits
const items = $input.all().map((i) => i.json).filter((j) => j && !j.__control && j.approvalId);
items.sort((a, b) => (a.updatedMs || 0) - (b.updatedMs || 0)); // oldest-first
const out = [];
for (let i = 0; i < items.length; i++) {
  const j = items[i];
  if (i > 0) await sleep(jitter());
  // 1. fetch VTADetails (public; no cookies needed)
  const det = await helpers.httpRequest({ method: 'GET', url: HOST + '/PublishedApprovals/VTADetails/?id=' + encodeURIComponent(j.approvalId), headers: { 'User-Agent': UA, Accept: 'text/html', 'Accept-Language': 'en-AU,en;q=0.9' }, returnFullResponse: true, ignoreHttpStatusErrors: true });
  if ([403, 429, 503].includes(det.statusCode)) throw new Error('ROVER detail ' + det.statusCode + ' at ' + j.vta + ' — possible block; aborting (high-water not advanced past here)');
  if (det.statusCode >= 400) { out.push({ json: { vta: j.vta, ok: false, error: 'detail ' + det.statusCode } }); continue; }
  // 2. POST the HTML to the app — it extracts the inline PDFs, parses, archives, gates
  const ing = await helpers.httpRequest({ method: 'POST', url: APP + '/api/rover/ingest/', headers: { Authorization: 'Bearer ' + TOKEN, 'Content-Type': 'application/json' }, body: JSON.stringify({ detailHtml: String(det.body) }), returnFullResponse: true, ignoreHttpStatusErrors: true });
  if (ing.statusCode >= 400) { out.push({ json: { vta: j.vta, ok: false, error: 'ingest ' + ing.statusCode, detail: String(ing.body).slice(0, 200) } }); continue; }
  // 3. success -> advance high-water monotonically
  if (j.updatedMs) sd.roverHighWaterMs = Math.max(sd.roverHighWaterMs || 0, j.updatedMs);
  const parsed = typeof ing.body === 'string' ? (() => { try { return JSON.parse(ing.body); } catch (e) { return {}; } })() : (ing.body || {});
  out.push({ json: { vta: j.vta, ok: true, variantsCreated: parsed.variantsCreated, variantsRefreshed: parsed.variantsRefreshed, amendment: parsed.amendment && parsed.amendment.status } });
}
return out;
